<script setup>
import {reactive,ref,onMounted,onBeforeUnmount} from 'vue'
import defaults from '../../config_defaults.json'
import {watchHostTheme} from './theme.js'
const props=defineProps({initialConfig:Object,api:Object,pluginId:{type:String,default:'ForumSignin'}})
const emit=defineEmits(['save','switch','close','layout'])
const model=reactive({...structuredClone(defaults),...(props.initialConfig||{})}),error=ref('')
const forums=[{id:'fengchao',name:'蜂巢',domain:'pting.club',url:'https://pting.club',fields:[['fengchao_api_key','Bearer Token']],toggle:'sync'}, {id:'yaowan',name:'药丸',domain:'invites.fun',url:'https://invites.fun',fields:[['yaowan_username','账号'],['yaowan_password','密码'],['yaowan_cookie','Cookie']],hint:'Cookie 失效时优先账密登录换新，否则取 CookieCloud'}, {id:'ssdforum',name:'SSD',domain:'ssdforum.com',url:'https://ssdforum.com',fields:[['ssdforum_cookie','Cookie']],hint:'Cookie 失效或为空时从 CookieCloud 获取'}]
function save(){emit('save',JSON.parse(JSON.stringify(model)))}
async function syncStats(){try{const r=await props.api.get(`plugin/${props.pluginId}/stats`);return r?.data??r}catch(e){error.value=e.message||'站点列表加载失败';return {}}}
let stopTheme;onMounted(()=>{stopTheme=watchHostTheme();syncStats();emit('layout',{maxWidth:'1000px'})});onBeforeUnmount(()=>stopTheme?.())
</script>
<template><div class="pt-center"><section class="card embedded-card" aria-label="论坛签到配置"><div class="card-head"><h2>论坛签到</h2><button class="btn ghost" @click="emit('close')">关闭</button></div><section class="win"><div class="group"><h3>基础设置</h3><div class="toggles-row"><label class="switch"><input v-model="model.enabled" type="checkbox" role="switch">启用插件</label><label class="switch"><input v-model="model.notify" type="checkbox" role="switch">发送通知</label></div><div class="grid"><label class="field"><span>签到 Cron</span><input v-model="model.cron" class="input"></label><label class="field"><span>失败重试次数</span><input v-model.number="model.retry_count" type="number" min="0" class="input"></label><label class="field"><span>重试间隔（分钟）</span><input v-model.number="model.retry_interval" type="number" min="1" class="input"></label></div></div></section><section class="win forum-config" style="margin-top:16px"><div class="forum-head"><h3>分论坛设置</h3></div><p class="hint">每个论坛独立启用与配置；开关关闭后不参与定时签到，凭据仅保存在本机配置中。</p><section v-for="forum in forums" :key="forum.id" class="site-card config-site"><div class="forum-head"><strong class="site-label"><span class="site-icon site-initial">{{forum.name.slice(0,1)}}</span><a class="forum-link" :href="forum.url" target="_blank" rel="noopener">{{forum.name}}</a><span class="forum-domain">{{forum.domain}}</span></strong><div class="row"><label v-if="forum.toggle" class="switch"><input v-model="model.timed_update_enabled" type="checkbox" role="switch">同步</label><label class="switch"><input v-model="model.enabled_sites" type="checkbox" :value="forum.id" role="switch">签到</label></div></div><div class="grid"><label v-for="field in forum.fields" :key="field[0]" class="field"><span>{{field[1]}}</span><input v-model="model[field[0]]" :type="field[0].includes('password')||field[0].includes('cookie')||field[0].includes('api_key')?'password':'text'" autocomplete="off" class="input"></label></div><p v-if="forum.hint" class="hint">{{forum.hint}}</p></section></section><div v-if="error" role="alert" class="alert">{{error}}</div><div class="footer"><button class="btn ghost" @click="emit('switch')">查看数据</button><button class="btn" @click="save">保存配置</button></div></section></div></template>
<style scoped src="./preview.css"></style>